    AND last_login_time <= #{userSearchRequest.lastLoginTimeEnd}
    AND account_locked_until >= #{userSearchRequest.accountLockedUntilStart}
    AND account_locked_until <= #{userSearchRequest.accountLockedUntilEnd}
    AND last_login_ip = #{userSearchRequest.lastLoginIp}

